53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_YEARS_THRESHOLD = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	const INSURANCE_VALUES: Record<string, number> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	// Spec: an item's base premium is 10 % of its insurance value.
71	// Dividing by 10 (rather than multiplying by 0.1) keeps gold amounts
72	// exact in floating point.
73	const VALUE_TO_PREMIUM_RATIO = 10;
74	
75	const insuranceValueOf = (itemType: string): number => {
76	  const insuranceValue = INSURANCE_VALUES[itemType];
77	  if (insuranceValue === undefined) {
78	    throw new Error(`Unknown item type: ${itemType}`);
79	  }
80	  return insuranceValue;
81	};
82	
83	const basePremiumOf = (itemType: string): number =>
84	  insuranceValueOf(itemType) / VALUE_TO_PREMIUM_RATIO;
85	
86	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
87	  values.reduce((total, value) => total + amountOf(value), 0);
88	
89	const BLOCK_SIZE = 3;
90	const COMPONENT_BLOCK_PREMIUM = 60;
91	
92	const COMPONENT_TYPES = ["rune", "moonstone"];
93	
94	const componentBlockAdjustment = (
95	  items: Item[],
96	  componentType: string,
97	): number => {
98	  const count = items.filter((item) => item.type === componentType).length;
99	  return count === BLOCK_SIZE
100	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
101	    : 0;
102	};
103	
104	const totalBasePremium = (items: Item[]): number =>
105	  sumBy(items, (item) => basePremiumOf(item.type)) +
106	  sumBy(COMPONENT_TYPES, (componentType) =>
107	    componentBlockAdjustment(items, componentType),
108	  );
109	
110	const surchargeFor = (
111	  items: Item[],
112	  rate: number,
113	  applies: (item: Item) => boolean,
114	): number =>
115	  sumBy(items, (item) =>
116	    applies(item) ? rate * basePremiumOf(item.type) : 0,
117	  );
118	
119	const isCursed = (item: Item): boolean => item.cursed === true;
120	
121	const isHighlyEnchanted = (item: Item): boolean =>
122	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
123	
124	const curseSurchargeFor = (items: Item[]): number =>
125	  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);
126	
127	const highEnchantmentSurchargeFor = (items: Item[]): number =>
128	  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
129	
130	const quotePremium = (
131	  items: Item[],
132	  customer: Customer,
133	  isFollowUpContract: boolean,
134	): number => {
135	  const basePremium = totalBasePremium(items);
136	  const itemSurcharges =
137	    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
138	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
139	  const loyaltyDiscount =
140	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
141	      ? basePremium * LOYALTY_DISCOUNT_RATE
142	      : 0;
143	  const followUpDiscount = isFollowUpContract
144	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
145	    : 0;
146	  return Math.ceil(
147	    basePremium +
148	      itemSurcharges +
149	      firstInsuranceSurcharge -
150	      loyaltyDiscount -
151	      followUpDiscount +
152	      PROCESSING_FEE,
153	  );
154	};
155	
156	const DEDUCTIBLE_PER_DAMAGE = 100;
157	const PAYOUT_CAP_MULTIPLIER = 2;
158	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
159	const REDUCED_REIMBURSEMENT_RATE = 0.5;
160	
161	// Spec: damage to items enchanted at 8 or above is reimbursed at 50 %
162	// (deductible is applied afterwards, per damage entry).
163	const reimbursementFor = (
164	  damage: Damage,
165	  damagedItem: Item | undefined,
166	): number =>
167	  (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
168	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
169	    : damage.amount;
170	
171	const initialCapFor = (policyItems: Item[]): number =>
172	  PAYOUT_CAP_MULTIPLIER *
173	  sumBy(policyItems, (item) => insuranceValueOf(item.type));
174	
175	// Spec: the deductible applies once per damage entry, after any
176	// reimbursement clause.
177	const payoutForDamage = (damage: Damage, policyItems: Item[]): number => {
178	  const damagedItem = policyItems.find(
179	    (item) => item.type === damage.itemType,
180	  );
181	  if (damagedItem === undefined) {
182	    throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
183	  }
184	  return reimbursementFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
185	};
186	
187	const settleClaim = (
188	  claimStep: ClaimStep,
189	  policyItems: Item[],
190	  remainingCapBefore: number,
191	): ClaimResult => {
192	  const uncappedPayout = sumBy(claimStep.incident.damages, (damage) =>
193	    payoutForDamage(damage, policyItems),
194	  );
195	  const payout = Math.floor(Math.min(uncappedPayout, remainingCapBefore));
196	  return { payout, remainingCap: remainingCapBefore - payout };
197	};
198	
199	export const runScenario = (scenario: Scenario): ScenarioOutput => {
200	  const remainingCaps = new Map<number, number>();
201	  return {
202	    results: scenario.steps.map((step, index) => {
203	      if (step.op === "claim") {
204	        const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
205	        const capBefore =
206	          remainingCaps.get(step.policy) ?? initialCapFor(policyItems);
207	        const result = settleClaim(step, policyItems, capBefore);
208	        remainingCaps.set(step.policy, result.remainingCap);
209	        return result;
210	      }
211	      return {
212	        premium: quotePremium(step.items, scenario.customer, index > 0),
213	      };
214	    }),
215	  };
216	};
217

