3	const readStdin = async (): Promise<string> => {
4	  let input = "";
5	  for await (const chunk of process.stdin) {
6	    input += chunk;
7	  }
8	  return input;
9	};
10	
11	const main = async (): Promise<void> => {
12	  const scenario = JSON.parse(await readStdin()) as Scenario;
13	  try {
14	    process.stdout.write(JSON.stringify(runScenario(scenario)) + "\n");
15	  } catch (error) {
16	    process.stderr.write(`${(error as Error).message}\n`);
17	    process.exitCode = 1;
18	  }
19	};
20	
21	main();
